(()=>{
const MASKS={"01_dark_lines": "data:image/png;base64,", "02_purple": "data:image/png;base64,", "03_teal": "data:image/png;base64,", "04_gold_yellow": "data:image/png;base64,", "05_orange_red": "data:image/png;base64,", "06_skin_tan": "data:image/png;base64,", "07_silver_white": "data:image/png;base64,"};
const MATERIAL='data:image/png;base64,';
const specs=[
 ['01_dark_lines',215,0.84,.58],['02_purple',290,1.00,.78],['03_teal',168,.90,.76],
 ['04_gold_yellow',52,1.08,.72],['05_orange_red',12,.96,.74],['06_skin_tan',34,.72,.58],['07_silver_white',205,.58,.35]
];
const cards=[...document.querySelectorAll('.card')];
cards.forEach(card=>{
 const base=new Image(); base.src='./mira-silver-base.jpg'; base.className='layer base'; card.append(base);
 const sw=document.createElement('i'); sw.className='silverWash'; card.append(sw);
 const bg=document.createElement('i'); bg.className='bgHolo'; card.append(bg);
 specs.forEach(([n])=>{
   const region=document.createElement('i');
   region.className='holo';
   region.dataset.mask=n;
   region.style.webkitMaskImage=`url("${MASKS[n]}")`;
   region.style.maskImage=`url("${MASKS[n]}")`;
   card.append(region);
 });
 const mat=document.createElement('i'); mat.className='material'; mat.style.backgroundImage=`url("${MATERIAL}")`; card.append(mat);
 const micro=document.createElement('i'); micro.className='micro'; card.append(micro);
 const sky=document.createElement('canvas'); sky.className='skyCanvas'; card.append(sky);
 const mask=new Image(); mask.src='./mira-jii.jpg'; mask.className='charMask'; card.append(mask);
});

const menu=document.querySelector('#menu'),
      viewer=document.querySelector('#viewer'),
      pair=document.querySelector('#pair'),
      status=document.querySelector('#status'),
      openMira=document.getElementById('openMira'),
      backBtn=document.getElementById('back'),
      startBtn=document.getElementById('start'),
      resetBtn=document.getElementById('reset'),
      maskToggle=document.getElementById('maskToggle');
let active=false,bB=null,bG=null,drag=false;
let target=0,current=0,raf=null;

const themeMeta=document.querySelector('meta[name="theme-color"]');
const show=v=>{
 menu.classList.toggle('active',!v);viewer.classList.toggle('active',v);
 document.documentElement.style.background='#08080a';
 document.body.style.background='#08080a';
 if(themeMeta)themeMeta.setAttribute('content','#08080a');
};
openMira.addEventListener('click',()=>show(true));backBtn.addEventListener('click',()=>show(false));
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const smoothstep=t=>t*t*(3-2*t);

function hueRGB(h,s,l){
 h=((h%360)+360)%360/360;
 const c=(1-Math.abs(2*l-1))*s, x=c*(1-Math.abs((h*6)%2-1)), m=l-c/2;
 let r=0,g=0,b=0,k=h*6;
 if(k<1)[r,g,b]=[c,x,0]; else if(k<2)[r,g,b]=[x,c,0]; else if(k<3)[r,g,b]=[0,c,x];
 else if(k<4)[r,g,b]=[0,x,c]; else if(k<5)[r,g,b]=[x,0,c]; else [r,g,b]=[c,0,x];
 return [Math.round((r+m)*255),Math.round((g+m)*255),Math.round((b+m)*255)];
}

const TAU=Math.PI*2;

// Dense, restrained star field: many small stars rather than game-like glow effects.
// All stars share the same celestial pole, so the whole field reads as diurnal motion.
const STAR_SEED=(()=>{
  const a=[]; let seed=91731;
  const rnd=()=>((seed=(seed*1664525+1013904223)>>>0)/4294967296);
  for(let i=0;i<620;i++){
    a.push({
      r:Math.sqrt(rnd()),
      a:rnd()*TAU,
      z:rnd(),
      b:.20+rnd()*.80,
      sz:.28+rnd()*.92,
      cross:rnd()>.955
    });
  }
  return a;
})();

function moonNoise(x,y){
  // Deterministic low-frequency lunar albedo. No glow/outline: the disc itself carries the texture.
  const n1=Math.sin(x*5.7+y*3.1)*.42;
  const n2=Math.sin(x*12.3-y*8.7)*.22;
  const n3=Math.cos(x*23.1+y*17.4)*.12;
  return n1+n2+n3;
}

function drawMoonEye(g,cx,cy,R,phaseDays,eye,tilt){
  // phaseDays: -5.5 ~= lunar day 24, 0 = new moon, +5 = lunar day 5.
  // Phase is calculated as a lit sphere, not as one circle punched from another.
  g.save();
  g.globalCompositeOperation='source-over';

  const N=72;
  const oc=document.createElement('canvas');
  oc.width=N; oc.height=N;
  const og=oc.getContext('2d');
  const im=og.createImageData(N,N), d=im.data;
  const phaseAngle=Math.PI - phaseDays*(TAU/29.53);
  const lx=Math.sin(phaseAngle), lz=Math.cos(phaseAngle);
  const stereoLight=(eye===0?-1:1)*.010;

  for(let j=0;j<N;j++){
    for(let i=0;i<N;i++){
      const x=(i+.5-N/2)/(N*.5), y=(j+.5-N/2)/(N*.5);
      const rr=x*x+y*y, k=(j*N+i)*4;
      if(rr>1){d[k+3]=0;continue}
      const z=Math.sqrt(Math.max(0,1-rr));
      // Directional sunlight on a sphere: this gives a straight terminator at half moon.
      const ndotl=x*(lx+stereoLight)+z*lz;
      const sun=Math.max(0,ndotl);
      // Slight limb darkening plus fixed mottled maria/crater texture.
      const limb=.64+.36*Math.pow(z,.45);
      const tex=moonNoise(x,y);
      const maria=.84 + tex*.11 - .07*Math.sin((x+.28)*9.4)*Math.sin((y-.11)*7.3);
      const lit=Math.pow(sun,.72);
      const earth=.010 + .018*z; // just enough to keep the new-moon disc materially present
      const v=clamp((earth + lit*.88)*limb*maria,0,1);
      const warm=clamp(v*1.02,0,1), cool=clamp(v*.96,0,1);
      d[k]=Math.round(216*warm);
      d[k+1]=Math.round(216*v);
      d[k+2]=Math.round(224*cool);
      d[k+3]=255;
    }
  }
  og.putImageData(im,0,0);
  g.drawImage(oc,cx-R,cy-R,R*2,R*2);

  // One eye begins opening before exact new moon and closes after it.
  // Its timing is independent of orbit, so the moon never waits for the eye.
  const window=2.65;
  const stereoBias=eye===0 ? -.10 : .10;
  const ad=Math.abs(phaseDays+stereoBias);
  let open=1-Math.min(1,Math.max(0,(ad-.18)/(window-.18)));
  open=open*open*(3-2*open);
  if(open>.012){
    const ew=R*.72;
    const eh=R*(.080 + .27*open);
    g.save();
    g.translate(cx,cy+R*.03);
    g.rotate(-tilt*.055 + (eye?0.006:-0.006));
    g.beginPath();
    g.moveTo(-ew*.52,0);
    g.quadraticCurveTo(0,-eh,ew*.52,0);
    g.quadraticCurveTo(0,eh,-ew*.52,0);
    g.closePath();
    g.fillStyle=`rgba(187,181,166,${.18+.74*open})`;
    g.fill();
    g.strokeStyle=`rgba(24,15,29,${.42+.48*open})`;
    g.lineWidth=Math.max(.55,R*.024);
    g.stroke();

    const irisR=R*(.094+.037*open);
    g.fillStyle=`rgba(86,54,104,${.64+.30*open})`;
    g.beginPath(); g.arc(0,0,irisR,0,TAU); g.fill();
    g.fillStyle=`rgba(5,4,7,${.88+.10*open})`;
    g.beginPath(); g.arc(0,0,irisR*.43,0,TAU); g.fill();
    g.restore();
  }
  g.restore();
}
function drawSky(card,eye,t){
  const cv=card.querySelector('.skyCanvas'),
        dpr=Math.min(devicePixelRatio||1,2),
        rect=card.getBoundingClientRect();
  if(!rect.width)return;

  const w=Math.max(2,Math.round(rect.width*dpr)),
        h=Math.max(2,Math.round(rect.height*dpr));
  if(cv.width!==w||cv.height!==h){cv.width=w;cv.height=h}

  const g=cv.getContext('2d');
  g.setTransform(dpr,0,0,dpr,0,0);
  const W=rect.width,H=rect.height;
  g.clearRect(0,0,W,H);

  // Quiet dark field. No nebula, rays or social-game-style effects.
  const grd=g.createRadialGradient(W*.48,H*.45,0,W*.48,H*.45,W*.82);
  grd.addColorStop(0,'#0d1220');
  grd.addColorStop(.56,'#040710');
  grd.addColorStop(1,'#010204');
  g.fillStyle=grd;
  g.fillRect(0,0,W,H);

  // Centre of the large name-band arc. The entire sky revolves around this point.
  const px=W*.50, py=H*.68;
  const stereoPhase=eye===0 ? -.010 : .010;
  const ang=t*1.72 + stereoPhase;
  const farX=Math.max(px,W-px), farY=Math.max(py,H-py);
  const maxR=Math.hypot(farX,farY)*1.13;

  // Dense full-field stars. Same angular motion; tiny depth/stereo offsets only.
  for(const s of STAR_SEED){
    const rr=s.r*maxR;
    const aa=s.a+ang;
    const par=(s.z-.5)*(eye===0?-1:1)*W*.0018;
    const X=px+Math.cos(aa)*rr+par;
    const Y=py+Math.sin(aa)*rr;
    if(X<-4||Y<-4||X>W+4||Y>H+4)continue;

    const hue=190+38*Math.sin((s.z+t*.22)*TAU);
    const alpha=.34+s.b*.58;
    const radius=s.sz*(.70+s.b*.48);
    g.fillStyle=`hsla(${hue},34%,${67+s.b*22}%,${alpha})`;
    g.beginPath(); g.arc(X,Y,radius,0,TAU); g.fill();

    // Only a few stars become tiny four-point marks. No large sparkles or bloom.
    if(s.cross){
      g.strokeStyle=`hsla(${hue},30%,86%,${alpha*.58})`;
      g.lineWidth=.48;
      const l=radius*2.7;
      g.beginPath(); g.moveTo(X-l,Y); g.lineTo(X+l,Y); g.moveTo(X,Y-l); g.lineTo(X,Y+l); g.stroke();
    }
  }

  // Barely visible concentric traces make the common rotation axis perceptible.
  g.strokeStyle='rgba(135,155,190,.026)';
  g.lineWidth=.45;
  for(let r=.18;r<1.12;r+=.20){
    g.beginPath(); g.arc(px,py,maxR*r,0,TAU); g.stroke();
  }

  // Moon: orbits by the same angular amount as the stars, but in reverse.
  // It passes the name area while continuously changing from lunar day 24 -> new -> day 5.
  const moonA= -t*1.72 - Math.PI*.54; // true circular orbit; stereo is positional, not an orbital phase cheat
  const orbitR=W*.31;
  const moonR=W*.050;
  // Raise the entire lunar orbit by 1.5 moon diameters (3 radii) from v0.5.
  const moonCx=px, moonCy=H*.39 - moonR*3;
  // Moon sits between the name band and character in depth, so give it a clearly
  // stronger binocular disparity than the distant star field. Both eyes still
  // follow the SAME true circle.
  const moonStereo=(eye===0?-1:1)*W*.0060;
  const moonX=moonCx+Math.cos(moonA)*orbitR+moonStereo;
  const moonY=moonCy+Math.sin(moonA)*orbitR;
  const phaseDays=t<0 ? t*5.53 : t*5.00;
  drawMoonEye(g,moonX,moonY,moonR,phaseDays,eye,t);
}

function paint(t){
 t=clamp(t,-1,1);
 const e=Math.sign(t)*smoothstep(Math.abs(t));
 cards.forEach((card,eyeIndex)=>{
   // A real hologram does not deliver exactly the same wavelength mix to both eyes.
   // Give the left/right images a small phase difference rather than a fixed tint.
   const stereoPhase=eyeIndex===0 ? -0.11 : 0.11;
   specs.forEach(([n,base,rate,sat])=>{
     const local=e + stereoPhase;
     const wobble=Math.sin((local*1.55 + base/360)*Math.PI)*13;
     const hue=base + local*248*rate + wobble*1.35;
     // "Dark lines" are now treated as just another holographic paint region.
     // They can be as bright as the surrounding painted areas.
     const light=n==='07_silver_white' ? .50 : .47;
     const s=n==='01_dark_lines' ? .92 : Math.min(.90,sat*.88);
     const lineExtra=n==='01_dark_lines' ? Math.sin(local*Math.PI*2.35)*34 : 0;
     const [r,g,b]=hueRGB(hue+lineExtra,s,light);
     const el=card.querySelector(`[data-mask="${n}"]`);
     el.style.backgroundColor=`rgb(${r},${g},${b})`;
     el.style.opacity=n==='07_silver_white' ? '.20' : (n==='01_dark_lines' ? '.86' : '.54');
   });
   // The exposed silver background is a major holographic surface.
   // Small tilt movements sweep through a much larger part of the spectrum.
   const bg=card.querySelector('.bgHolo');
   const q=e+stereoPhase;
   const bh1=188 + q*255;
   const bh2=304 - q*230;
   const bh3=58  + q*285;
   const c1=hueRGB(bh1,.68,.45), c2=hueRGB(bh2,.64,.42), c3=hueRGB(bh3,.62,.46);
   const pos=50 + q*36;
   bg.style.background=`linear-gradient(121deg,
     rgb(${c1[0]},${c1[1]},${c1[2]}) 0%,
     rgb(${c2[0]},${c2[1]},${c2[2]}) ${Math.max(18,pos-24)}%,
     rgb(${c3[0]},${c3[1]},${c3[2]}) ${Math.min(82,pos+24)}%,
     rgb(${c1[0]},${c1[1]},${c1[2]}) 100%)`;
   bg.style.opacity=(.48+Math.abs(q)*.20).toFixed(3);
   const mat=card.querySelector('.material');
   mat.style.transform=`translate(${(e+stereoPhase*.35)*1.8}px,${e*.8}px) scale(1.012)`;
   mat.style.opacity=(.34+Math.abs(e)*.07).toFixed(3);
   drawSky(card,eyeIndex,t);
 });
}
function animate(){
 current += (target-current)*0.105; // sensor smoothing; celestial motion stays linear through neutral
 if(Math.abs(target-current)<0.0005) current=target;
 paint(current);
 raf=requestAnimationFrame(animate);
}
animate();

function setTarget(v){target=clamp(v,-1,1)}
function orient(e){
 if(!active)return;
 if(bB===null){bB=e.beta||0;bG=e.gamma||0}
 let x=((e.gamma||0)-bG)/11,y=((e.beta||0)-bB)/18;
 if(matchMedia('(orientation:portrait)').matches){let q=x;x=y;y=-q}
 setTarget(x+y*.18);
}
startBtn.addEventListener('click',async()=>{
 try{
  if(typeof DeviceOrientationEvent==='undefined'){status.textContent='センサー非対応 / ドラッグ操作可';return}
  if(typeof DeviceOrientationEvent.requestPermission==='function'&&await DeviceOrientationEvent.requestPermission()!=='granted'){
   status.textContent='センサー許可なし / ドラッグ操作可';return
  }
  bB=bG=null;active=true;addEventListener('deviceorientation',orient,true);
  startBtn.textContent='TILT ACTIVE';status.textContent='現在角度を基準に設定';
 }catch(e){status.textContent='センサーを開始できません'}
});
resetBtn.addEventListener('click',()=>{bB=bG=null;setTarget(0)});
maskToggle.addEventListener('click',()=>{const off=cards[0].classList.toggle('maskOff');cards[1].classList.toggle('maskOff',off);maskToggle.textContent=off?'MASK OFF':'CHAR MASK';});
function pointer(e){
 const r=pair.getBoundingClientRect();
 setTarget(((e.clientX-r.left)/r.width-.5)*3.2);
}
pair.onpointerdown=e=>{drag=true;pair.setPointerCapture(e.pointerId);pointer(e)};
pair.onpointermove=e=>{if(drag)pointer(e)};
pair.onpointerup=pair.onpointercancel=()=>drag=false;

if('serviceWorker'in navigator){
 addEventListener('load',async()=>{
   try{
     // v1.1 development mode: update the cleanup worker, then remove stale registrations/caches.
     await navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'});
     const regs=await navigator.serviceWorker.getRegistrations();
     setTimeout(()=>regs.forEach(r=>r.unregister()),1200);
     if('caches'in window){
       const keys=await caches.keys();
       await Promise.all(keys.map(k=>caches.delete(k)));
     }
   }catch(e){}
 });
}
})();